  [1472] = { "Il divoratore di anime", nil, nil, nil, nil, 0xc90e9da6, nil, nil, nil, nil, ".mmmm" },
  [1474] = { "Il vincolo", nil, nil, nil, nil, 0x5926988f, nil, nil, nil, nil, ".mmmm" },
  [1475] = { "Nel Temple of Atal'Hakkar", "Raccogli 10 Atal'ai Tablets per Brohann Caskbelly, a Stormwind.", "Secondo la leggenda, il Temple of Atal'Hakkar è un santuario sacro dedicato all'antico dio Hakkar the Soulflayer. Custodito da una feroce tribù di troll chiamata Atal'ai, si dice che il tempio sia inespugnabile.\n\nOra che è sprofondato sotto la Pool of Tears, recuperare manufatti dal tempio è ancora più difficile. Ma è proprio quello che ho bisogno che tu faccia, {name}.\n\nAiutami raccogliendo le Atal'ai Tablets intatte. Portamele e tornerò all'Explorers' Guild da eroe. Condivideremo la gloria insieme.", "Mentre il crepuscolo scende lentamente sulla mia carriera, mi rivolgo a te, {name}, perché tu mi aiuti nella mia ultima missione per l'Explorers' League. Se le mie vecchie ossa trovassero la forza di sfidare lo Swamp of Sorrows e il tempio sommerso, combatterei proprio al tuo fianco.\n\nL'orgoglio mi rende difficile chiederti aiuto per raccogliere le Atal'ai Tablets. Ma la vecchiaia lo rende necessario.\n\nTi prego, aiutami, {name}. Voglio ritirarmi dall'Explorers' League dopo aver portato a termine il loro ultimo incarico.", "Le Atal'ai Tablets! Grazie, {name}!\n\nUna volta consegnate all'Explorers' League, i nostri nomi passeranno insieme alla storia. Hai aiutato un vecchio nano a compiere il suo ultimo dovere nella vita. Per questo ti sono eternamente grato.", 0xa403bf55, 0x7f6d6719, 0x09e59f8e, 0xa14e8aae, 0x4584ecfd, "....." },
  [1477] = { "Rifornimenti vitali", "Parla con il Watchmaster Sorigal.", "I nostri maghi stanno conducendo ricerche a Nethergarde Keep, nelle Blasted Lands, ricerche vitali per la nostra comprensione dei Dark Portal. Hanno bisogno di rifornimenti quasi continui, ma la nostra linea di rifornimento per Nethergarde è fragile.\n\nDevi aiutarci a far arrivare i rifornimenti a Nethergard. Presentati al Watchmaster Sorigal, a Darkshire, e fa' ciò che ti chiede. Questo compito ti porterà in terre ostili, {name}. Preparati.", nil, "Ti ha mandato Andromath? Molto bene. Ho un compito importante per te...", 0x9d8ff76c, 0x71a7d15d, 0x3ad8891c, nil, 0x84281d45, "...m." },
  [1483] = { nil, "Parla con Ziz Fizziks, a Windshear Crag.", "La Venture Company ha rubato molte delle migliori menti goblin, ma di tanto in tanto abbiamo l'occasione di rubarne qualcuna indietro.\n\nTempo fa, la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle: uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ne è rimasto così sconcertato che mi ha supplicato di trovargli un nuovo impiego nella Tinkers' Union. Gli ho affidato qualche compito, ma potrebbe aver bisogno di aiuto.\n\nForse potresti andare a vedere come se la cava, per me? È di stanza al margine occidentale di Windshear Crag.", nil, "Pensavo che i capi della Venture Company fossero negrieri, ma poi ho conosciuto Sputtervalve, il più crudele di tutti!\n\nAh! Comunque è meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.", nil, 0xd85f0063, 0x5c119beb, nil, 0x4bc25ea8, "m..m." },
  [1486] = { "Pelli deviate", "Nalpak, nelle Wailing Caverns, vuole 20 Deviate Hides.", "Mentre Naralex sprofondava sempre più nel suo incubo, una strana razza di bestie è emersa da sotto le Barrens nelle Wailing Caverns.\n\nQueste creature deviate hanno proprietà strane, ultraterrene. Anche se di natura malvagia, secondo me dalla loro esistenza qui a Kalimdor può venire qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nella lavorazione del cuoio.\n\nSe te la senti, avventurati nelle grotte sottostanti e recupera qualche pelle deviata.", "Sono molto interessato a esaminare le pelli delle creature deviate che hanno infestato queste grotte. Hai avuto fortuna a raccoglierne qualcuna, {class}?", "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, {name}.\n\nGrazie per la tua dedizione.", 0x1bed65d5, 0x27d84e49, 0x3e2a3766, 0x0dcdb776, 0x715ed582, "....." },
  [1487] = { "Sradicamento dei deviati", "Ebru, nelle Wailing Caverns, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.", "Naralex aveva un obiettivo nobile.\n\nIl nostro grande capo aspirava a entrare nell'Emerald Dream e aiutare queste terre aspre a tornare la foresta rigogliosa di un tempo. Ma qualcosa è andato terribilmente storto.\n\nIl sogno di Naralex si è trasformato in un incubo e creature corrotte hanno cominciato ad abitare le caverne.\n\nMentre alcuni Disciples of Naralex cercano di risvegliare il nostro maestro, a me preme liberare queste grotte dalle bestie malvagie.\n\nSfida le caverne, {name}, e sradica la progenie deviata.", "{name}, noi, i Disciples of Naralex, abbiamo bisogno del tuo aiuto. Il nostro numero si assottiglia mentre il nostro maestro è intrappolato nel suo incubo distorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.\n\nTi supplico, entra nelle grotte e fa' guerra alle creature deviate!", "Come Disciple of Naralex, lodo il tuo coraggio, {name}.\n\nIl tuo aiuto nel ripulire le caverne è il primo passo nella nostra lunga lotta per vedere le Barrens risanate.\n\nGrazie, e che tu possa prosperare.", 0x97d1256c, 0x65cf05d4, 0xc616bee2, 0x56e545f4, 0x09635dc9, "....." },
  [1491] = { "Bevande intelligenti", "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix, a Ratchet.", "Va bene, le corna di raptor non hanno funzionato granché. Ma non importa: nessuno si è arricchito al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande intelligenti!\n\nC'è una sostanza chiamata Wailing Essence, e credo che sia la causa delle strane piante e degli strani animali delle Barrens. Procuramene un po' e la proverò nella mia bevanda!\n\nHo sentito che l'essenza si accumula nelle creature ectoplasmatiche delle Wailing Caverns, a ovest. Dai la caccia a quelle creature e raccogli l'essenza.", "Dov'è la mia wailing essence?", "Ottimo, l'hai presa! Non vedo l'ora di provarla. Mi farà fare una fortuna, lo so!\n\nGrazie, {name}. Prendi questo, e quando sarò ricco te ne manderò ancora, promesso!", 0x3bd3c186, 0x92e0631f, 0x440930e0, 0x1ed90584, 0x985f6f88, "....." },
