  [1527] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [1528] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", nil, nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, nil, nil, 0xf9228c66, "..mm." },
  [1529] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", nil, nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, nil, nil, 0xf9228c66, "..mm." },
  [1530] = { "Il richiamo dell'acqua", "Trova Brine nelle Southern Barrens.", "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.\n\nIl suo potere scorre, erode e purifica ogni genere di cosa. Troverai la sua capacità di guarire e rigenerare impareggiabile, ma solo quando è pura.\n\nQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia una risorsa vitale.\n\nSe desideri la water sapta, trova Brine nel profondo delle Southern Barrens. La sua casa è continuamente molestata dai quilboar di quella zona.", nil, "Sì?\n\nMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere qui, nella parte più remota delle Barrens, con la minaccia dei quilboar tutt'intorno e senza protezione? Beh, abbiamo tutti le nostre ragioni per giustificare come agiamo. La vera domanda è: cosa porta un umile membro della razza {race} negli angoli più remoti delle Barrens a parlare con una donna che evidentemente non si preoccupa del proprio benessere?\n\nScommetto che entrambi conosciamo la risposta.", 0x1f0e11aa, 0xee4ba4c3, 0xfd15e1c1, nil, 0xfab4a730, "...m." },
  [1534] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1535] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1536] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1559] = { nil, nil, nil, nil, "Quindi sei un ingegnere, eh? Be', per l'aiuto con quelle perle, ecco la ricetta delle bombe accecanti.\n\nBuona fortuna, e cerca di non accecarti!", nil, nil, nil, nil, 0x7a64992c, "mmmm." },
  [1578] = { "Rifornire il fronte", "Porta $N1 Copper Axes e $N2 Copper Chain Belts a Thorvald, nella torre di guardia meridionale di Loch Modan", "I montanari di Loch Modan stanno combattendo i trogg, e hanno un bel daffare! Hanno bisogno di rifornimenti continui di armature e armi nuove se vogliamo tenere a bada quei trogg.\n\nPer questo il mio collega Thorvald è lì, a cercare di tenere i montanari ben equipaggiati. Quindi, se forgiassi qualche ascia di rame e qualche cintura di maglia di rame e le portassi a Thorvald, te ne sarebbe grato. Potrebbe persino condividere con te il suo sapere.\n\nThorvald si trova nella torre di guardia meridionale di Loch Modan.", "Non ho tempo per chiacchierare. Hai affari con me?", "Ah, scusami! Non avevo capito che eri qui per aiutare a rifornire le nostre truppe. La roba che hai forgiato sarà di grande aiuto!\n\nEcco gli schemi per un'armatura. Spero ti siano utili.", 0xc30dcf6c, 0xa979298d, 0x30473b15, 0xec2e191f, 0xf823104b, "....." },
  [1579] = { nil, "Porta 8 Gaffer Jacks a Wizbang Cranktoggle, ad Auberdine.", "Sono venuto ad Auberdine per la tranquillità. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il chiasso di Ironforge!\n\nCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Ho fatto cadere in mare la mia scatola di Gaffer Jacks! Mi servono i miei Gaffer Jacks!\n\nNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano potresti avere fortuna...", "Hai trovato i miei gaffer jack, {name}? Senza i miei gaffer jack non posso accordare i miei stintle peg!", "Non posso credere che tu li abbia trovati! Devi essere il membro più fortunato della razza {race} in tutto Kalimdor!", nil, 0xb6cf36d8, 0xf09fa27e, 0x68a8175d, 0x9be37eba, "m...." },
  [1580] = { nil, "Porta 12 Electropellers a Wizbang Cranktoggle, ad Auberdine.", "Sappiamo che hai fortuna, ma... quanta fortuna hai, {name}?\n\nUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago dove provare la mia nuova anatra da richiamo esplosiva semovente, e credo di essere stato un po' alticcio... perché sono svenuto e mi sono svegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia sacca di Electropellers era sparita! Devo averli fatti cadere in acqua!\n\nMi servono quegli Electropellers! Forse puoi ripescarli in qualche lago o torrente di Darkshore...", "Hai trovato qualche electropeller? Mi servono, se devo continuare le mie ricerche sulle anatre da richiamo...", "Non ci credo! Li hai trovati! Sei il miglior pescatore che abbia mai visto!\n\nGrazie, {name}. E tieni, prendi questi. Anche se sei così <bravo/brava> che probabilmente non ti servono, ti aiuteranno a pescare.", nil, 0xdc46859a, 0x642310a5, 0xf9546f58, 0xc63f8173, "m...." },
  [1581] = { "Elisir per i Bladeleafs", "Porta 6 Elixirs of Lion's Strength e 2 Elixirs of Minor Defense a Syral Bladeleaf, a Dolanaar.", "La nostra bottega di erbe e alchimia va a gonfie vele, ma mio marito passa così tanto tempo a preparare pozioni che non abbiamo mai tempo per noi.\n\nPuoi aiutarci?\n\nSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho delle erbe rare che potrebbero tornarti utili.", "Salve, {name}. Hai gli elisir da scambiare?", "Sono ben miscelati. Metti grande cura nel tuo mestiere, {name}, ed è importante per un alchimista.\n\nEcco le tue erbe, appena raccolte. Usale bene.", 0x55e6a1a0, 0x4cd053d4, 0x114405e0, 0x486738da, 0xd85fcf4b, "....." },
  [1582] = { nil, "Porta 1 Embossed Leather Glove, 5 Embossed Leather Boots e 5 Embossed Leather Cloaks a Lotherias, a Darnassus.", "Noi di Darnassus, soprattutto noi artigiani, siamo molto impegnati. I giovani avventurieri non vedono l'ora di mettersi alla prova nelle terre selvagge, e hanno continuamente bisogno di provviste.\n\nSe mi aiuti a evadere i miei ordini di articoli di cuoio, forse potrò insegnarti una tecnica avanzata di conciatura.", "Salute, {name}.", "Sì, sono pezzi buoni. Hai una mano abile e occhio per i dettagli. Il tuo futuro da conciatore è promettente.\n\nEcco, {name}. Lascia che ti mostri il modello per fare il Moonglow Vest.", nil, 0xd2ae52ab, 0x86455e3c, 0x1355ea4c, 0x60bb3c3a, "m...." },
  [1598] = { "Il tomo rubato", "Recupera i Powers of the Void per Drusilla La Salle.", "Ehi, tu! {name}, giusto?\n\nSpero che tu sia <convinto/convinta> di voler diventare <uno/una> <stregone/strega>, perché se non sai cavartela da <solo/sola>, finirai per farti trascinare a fondo.\n\nDevo istruirti, ma prima devo assicurarmi che tu sia abbastanza forte.\n\nC'era un novizio che studiava all'abbazia ed è scappato per unirsi alla Defias Brotherhood. Perché mi interessa? Be', ha rubato alcuni libri importanti.\n\nUno di questi è proprio un libro che volevo per me, i Powers of the Void. Rubalo per me: lo tengono nascosto nella loro tenda nei vigneti.", "Rubare il libro di persona avrebbe dato troppo nell'occhio. Che fortuna che uno dei loro tirapiedi abbia fatto il lavoro sporco per me.", "Eccellente... Non sono mai riuscita a mettere le mani su questo testo: era custodito in un'ala protetta della biblioteca, e aggirarmi da quelle parti sarebbe sembrato sospetto.\n\nBe', hai fatto un buon lavoro a procurartelo, e sono convinta che tu sia in grado di gestire un imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.", 0x88b1dee6, 0x8e23bc14, 0x4748064a, 0xdb594d3a, 0x048d8e41, "....." },
  [1599] = { "Inizi", "Porta 3 Feather Charms ad Alamar Grimm, ad Anvilmar.", "Devi essere <il/la> <nuovo/nuova> <stregone/strega> di cui tutti bisbigliano. Qualcuno deve averti preso in simpatia, se mi hanno chiesto di sottrarre tempo alle mie ricerche per cominciare il tuo addestramento.\n\nNon preoccuparti, non te ne farò una colpa.\n\nIl più semplice degli incantesimi di evocazione che imparerai è quello dell'imp. Prima di insegnartelo, però, devi dimostrare di avere le capacità magiche e fisiche necessarie.\n\nPortami tre feather charms dai novizi Frostmane della grotta a sud-ovest.", "Quei feather charms che portano i novizi hanno una sorta di potere magico. Sarà interessante studiarli. Non me lo sarei aspettato dai troll.", "Molto bene, molto bene! Te la sei cavata bene, {name}. Forse l'interesse che ti stanno dimostrando è meritato, dopotutto.\n\nSarà compito degli altri deciderlo, ammesso che il tuo imp non ti sopraffaccia e stronchi la tua carriera sul nascere. Per ora mi basta sapere che probabilmente sopravvivrai ai tuoi primi mesi come {class}.\n\nUna parola sull'imp, {name}. Come sa chi è della razza {race}, non lasciarti ingannare dalle dimensioni: la sua magia può essere molto pericolosa.", 0xf98072ec, 0xf994bd58, 0xa842c92b, 0xeeb2dc13, 0xe52d5af0, "....." },
  [1618] = { "Equipaggiare Redridge", "Tormus Deepforge vuole che porti $N1 Runed Copper Belts e $N2 Heavy Copper Mauls a Verner Osgood, a Redridge.", "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel daffare!\n\nRedridge è attaccata di continuo dagli orchi Blackrock, e le loro scorte di equipaggiamento sono sempre scarse. Se li aiutassi, sono sicuro che il loro fabbro, Verner Osgood, ti insegnerebbe un trucco o due.", "Spero che tu mi porti buone notizie da Ironforge. Perché non so più dove sbattere la testa!", "Grazie, {name}. Questo mi aiuterà tantissimo. Con gli orchi Blackrock che attaccano dalla Stonewatch Keep e gli gnoll di Redridge in agguato sulle colline a nord, devo sempre riparare armature e forgiare armi nuove per le nostre truppe.\n\nLe provviste che hai portato mi daranno un attimo di respiro. Avrò abbastanza tempo per insegnarti qualcosa...", 0x2d039f79, 0x87de2a39, 0x66c6d741, 0x49945919, 0x462fb187, "....." },
  [1638] = { "L'addestramento di un guerriero", "Parla con Harry Burlguard.", "Hai dimostrato di essere <un/una> <guerriero/guerriera> capace, {name}. Ma sei ancora giovane e hai molto da imparare.\n\nParla con Harry Burlguard: di solito è alla taverna Pig and Whistle, nella Old Town di Stormwind. Harry è un vecchio veterano e un buon maestro. Può insegnarti qualche mossa che ti terrà in vita più a lungo.", nil, "Oh oh! Bevi qualcosa con me, {name}. Fuori sembri una persona tosta, ma vediamo se il tuo stomaco regge qualche boccale del più forte del Pig and Whistle!!\n\nOppure... eri qui per una lezione?", 0x93c881d5, 0x0aef52fa, 0x0ff82d16, nil, 0x11af52b0, "...m." },
  [1639] = { "Bartleby l'ubriaco", "Parla con Bartleby.", "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.\n\nVedi quell'ubriaco laggiù in fondo al bancone? Bartleby? Voglio che tu prenda il suo boccale.\n\nAh, e se conosci Bartleby, sai che non te lo darà di sua spontanea volontà.", nil, "Salve, <bel/bella> <ragazzo/ragazza>! Che ci fa un tipino schizzinoso come te al Pig and Whistle? Occhio, o potresti romperti un'unghia...", 0x1785381a, 0x423c9e83, 0x1cf66148, nil, 0x99442b95, "...m.", nil, nil, nil, nil, 0x4102c003 },
  [1640] = { "Batti Bartleby", "Batti Bartleby, poi parlagli.", "Vuoi cosa?? Sei <matto/matta>!\n\nL'unico modo in cui avrai questo boccale è strapparmelo dalle mie fredde dita morte...", "L'unico modo in cui avrai questo boccale è strapparmelo dalle mie fredde dita morte...", "Sei molto più <tosto/tosta> di quanto sembri!", 0x26ecfd0d, 0x3f5bb9b0, 0xe0771850, 0xa0dfd961, 0xdc83d2d5, "....." },
  [1641] = { "Il Tome of Divinity", nil, nil, nil, "Qui a Stormwind sono responsabile di avviare i paladini sul cammino di una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dalla Scourge e da altre minacce.\n\nÈ giunto il momento che tu faccia il primo passo verso la vera virtù. Se accetti, ti darò un Book of Divinity. Studiandolo, imparerai qualcosa sulla Luce e su ciò che ci si aspetta da te. Se lo capirai e ne sarai in grado, riuscirai ad acquisire capacità più grandi.", 0xe91f21c0, nil, nil, nil, 0xde6e2d42, ".mmm." },
  [1642] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", "In ogni cosa un paladino deve riflettere la Luce che sostiene la nostra forza. Per uno della nostra specie, aspirare al divino non significa aspirare a diventare un dio: aspiriamo a essere buoni in ogni azione.\n\nAnche se in questi tempi duri siamo chiamati a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dai cittadini di Azeroth. Compassione, pazienza, coraggio: queste cose significano per un paladino quanto la forza in battaglia.\n\nSappilo bene e non dimenticarlo mai.", nil, "Salve di nuovo, {name}. Come procedono i tuoi studi del Tome of Divinity?\n\nAllora dovresti essere <pronto/pronta> a essere <messo/messa> alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre: atti di compassione e comprensione; persone che hanno bisogno di aiuto; creature da uccidere.\n\nDimostrando di avere la pazienza di aiutare gli altri, specialmente i meno fortunati, dimostri di essere al servizio della Luce e di avere una mente salda.", 0xe91f21c0, 0x0f3ca705, 0x0d5218fa, nil, 0x075c2620, "...m." },
  [1643] = { "Il Tome of Divinity", "Cerca Stephanie Turner nel Trade District di Stormwind.", "Il tuo compito allora, {name}, è trovare qui a Stormwind qualcuno che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenti. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, la persona deve avere intenzioni nobili e contare sulla tua gentilezza.\n\nFallo e torna da me quando avrai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere <un/una> <paladino/paladina> della Luce.", nil, "Oh, salve, tesoro. Come vanno le tue avventure? Oh, sono così contenta di sentire che va tutto bene.\n\nOh, io? Grazie di chiederlo: sto bene, tutto considerato.\n\nL'aumento dei mercanti ha un po' ridotto la quantità di cuoio e stoffa che la gente è disposta a cedere di questi tempi, quindi è stato più difficile fare vestiti per i bambini dell'orfanotrofio, ma ce la faremo. Per \"noi\" intendo mio marito e io. È a Ironforge a cercare aiuto tra i cittadini di laggiù.", 0xe91f21c0, 0xce0e1021, 0x63f1ddfe, nil, 0x3d88e066, "...m." },
  [1644] = { "Il Tome of Divinity", "Porta 10 Linen Cloth a Stephanie Turner, a Stormwind.", "Poveri cari, la maggior parte di loro non ha più una famiglia a causa degli attacchi della Scourge nell'ultimo decennio.\n\nMio marito John raccoglie i materiali con cui faccio camicie e pantaloni per i bambini, ma non ho avuto nemmeno il tempo di farli. Sono troppo presa a mettere il cibo nei loro piatti e a dar loro un tetto sopra la testa.\n\nCome dici? Saresti <disposto/disposta> ad aiutare? Oh, grazie alla Luce, e grazie a te, {name}.\n\nSe potessi portarmi un po' di linen cloth per cucire vestiti ai bambini, mi aiuteresti tantissimo.", "Spero che il mio John abbia più fortuna a Ironforge. Non ama affatto i suoi viaggi laggiù perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore così buono.\n\nAlcuni anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se qualcosa nell'aria annunciasse un grande cambiamento. Ma chi può saperlo?", "Grazie, {name}, grazie infinite!\n\nI bambini saranno felicissimi, e mi hai fatto risparmiare tanto tempo. Ora potrò concentrarmi sugli altri bisogni dei bambini e, spero, il mio John potrà tornare a casa prima del previsto.\n\nGrazie ancora, {name}. Sapevo di poter contare sulla carità altrui. Che la Luce sia con te.", 0xe91f21c0, 0xf1310977, 0xb01329b2, 0x903a4103, 0x6226b5ac, "....." },
  [1645] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1646] = { "Il Tome of Divinity", "Parla con Tiza Battleforge, a Ironforge.", "In ogni cosa un paladino deve riflettere la Luce che sostiene la nostra forza. Per uno della nostra specie, aspirare al divino non significa aspirare a diventare un dio: aspiriamo a essere buoni in ogni azione.\n\nAnche se in questi tempi duri siamo chiamati a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dai cittadini di Azeroth. Compassione, pazienza, coraggio: queste cose significano per un paladino quanto la forza in battaglia.\n\nSappilo bene e non dimenticarlo mai.", nil, nil, 0xe91f21c0, 0x04be03fc, 0x0d5218fa, nil, nil, "...mm" },
  [1647] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1648] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1649] = { "Il Tome of Valor", "Parla con Duthorian Rall, a Stormwind.", "Il valore, e tutte le virtù che lo accompagnano, sono come minerali rari: devi custodirli quando li trovi per il loro valore, ma devi anche prenderti il tempo di estrarli... raffinarli. Quando vengono mescolati nel modo giusto, si forma una lega resistente, a volte infrangibile persino dai colpi più potenti.\n\nQuesta forza, la tua fede, il tuo coraggio, devono essere messi alla prova. Devi imparare a non perdere mai la fede e a capire che con il potere della Luce puoi superare cose che la maggior parte degli altri non può.", nil, "Ah, vuoi chiedermi una prova di valore. Splendido.\n\nCi sono molti compiti in città e nelle terre circostanti che sono una vera sfida, e potrebbero servire <un/una> <uomo/donna> con le tue capacità.\n\nQuesta prova non va presa alla leggera, {name}. Questa, come molte cose lungo il nostro cammino, potrebbe costarci la vita. La chiesa desidera sempre rafforzare i suoi ranghi, ma comprende i sacrifici necessari per assicurarsi che i paladini al suo servizio ne siano degni.\n\nSei <pronto/pronta>?", 0xdaebf666, 0x0f3ca705, 0x19f0af5d, nil, 0x370b9c7b, "...m.", nil, nil, nil, nil, 0xeacd036c },
  [1650] = { "Il Tome of Valor", "Trova Daphne Stilwell a Westfall.", "Bene! La tua mancanza di esitazione è un chiaro segno che sei <pronto/pronta> e <desideroso/desiderosa> di metterti alla prova. E così sia.\n\nAll'estremità del Longshore di Westfall, una casetta guarda sull'oceano. Lì vive una coppia, gli Stilwell. Jordan è un fabbro straordinario ed è andato a Ironforge a incontrare i nani per un po'. Ma questo ha lasciato Daphne, sua moglie, sola e senza protezione.\n\nI rapporti suggeriscono che i Defias abbiano ormai preso il controllo della zona; Daphne potrebbe aver bisogno di protezione da quei furfanti. Va' lì.", nil, "Salve, {name}. A giudicare da tutta quell'armatura e da quell'arma, immagino che o sei qui per cercare di prenderti la mia terra, o la chiesa ha finalmente mandato qualcuno a proteggermi mentre il mio Jordan è via.\n\nBeh, lascia che mi presenti: sono Daphne Stilwell. Piacere.\n\nNon sei in ritardo... ho ucciso solo una mezza dozzina di quei farabutti dall'ultima alba. Sono stati un po' lenti a girare la curva lassù, ma probabilmente ti hanno visto arrivare, il che significa che saranno qui da un momento all'altro.", 0xdaebf666, 0xcafbffbb, 0x9e791513, nil, 0xd85dbe60, "...m." },
  [1651] = { "Il Tome of Valor", "Difendi Daphne Stilwell dall'attacco dei Defias.\n\nPer riuscire, nessuno dei vostri spiriti deve lasciare le proprie spoglie mortali.\n\nQuando ci sarai <riuscito/riuscita>, parla di nuovo con Daphne Stilwell.", "Ora, scommetto che torneranno presto, quindi preparati.\n\nHo un fucile in casa. Lo prendo e sarò pronta ad aiutarti, ma per lo più dovrai cavartela da <solo/sola>.\n\nNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi che hanno mandato prima.\n\nChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.\n\nResistiamo vicino alla casa!", "Resistiamo vicino alla casa!", "Ce l'abbiamo fatta, {name}! Grazie per l'aiuto. Sei <stato/stata> davvero <straordinario/straordinaria> là fuori. Non avrei mai pensato che un paladino potesse tenere testa a tanti nemici insieme.\n\nHai davvero dimostrato coraggio contro forze soverchianti.", 0xdaebf666, 0x891ebe27, 0xa90e2959, 0x52f37378, 0x0f46273c, "....." },
  [1652] = { "Il Tome of Valor", "Parla con Duthorian Rall, a Stormwind.", "Ti prego, torna da Duthorian e fagli sapere che per ora sono al sicuro. Devo ringraziare te e la chiesa per questo.\n\nManderà a dire a Ironforge che il mio Jordan non ha nulla da temere.\n\nOh, quanto mi manca mio marito. Non vedo l'ora che torni.", nil, "Allora ci rivediamo, {name}, e vedo che sei di ottimo umore.\n\nLa casa degli Stilwell sarà al sicuro per un altro giorno, e dal tuo racconto vedo che i pericoli non sono mancati. Ben fatto.\n\nDaphne e Jordan hanno aiutato molto la chiesa, e farti proteggere la loro proprietà, e le loro stesse vite, era il minimo che potessimo fare per loro.\n\nPer il tuo valore sarai <ricompensato/ricompensata>.", 0xdaebf666, 0x0f3ca705, 0xc192be15, nil, 0xccb181a9, "...m." },
  [1653] = { "La prova della rettitudine", "Parla con Jordan Stilwell, a Ironforge", "In realtà non ho dubbi che Jordan in persona vorrebbe ringraziarti, e visto che mi serve un messaggero per fargli sapere che sua moglie è al sicuro, credo che tu sia la scelta perfetta.\n\nJordan stava per diventare un paladino della Luce prima che la dedizione al mestiere di suo padre lo portasse su un'altra strada: conosce a fondo il nostro modo di vivere ed è considerato tra i nostri più fedeli.\n\nDovrebbe essere ancora a Ironforge: di giorno gli piace lavorare fuori dalle porte, per via dell'aria fresca di montagna.", nil, "Buongiorno, {name}. La Luce è con te, spero?\n\nCome dici? Ti ha mandato Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai se me ne fossi andato. Ti prego, dimmi che... oh, grazie al cielo. Sono così felice che sia al sicuro. I Defias erano una minaccia molto prima di questi attacchi, ma ora i consiglieri del re non possono negarlo.\n\nCos'altro aveva da dire Duthorian?\n\nSei tu la persona mandata a proteggere mia moglie? Allora ti ringrazio ancora, {name}. Non potrei immaginare una prova di valore migliore di questa.", 0xcdb318ba, 0x81a2ff9b, 0x9423b858, nil, 0xcf755a7e, "...m." },
  [1654] = { "La prova della rettitudine", "Usando le Jordan's Weapon Notes, trova del Whitestone Oak Lumber, il Bailor's Refined Ore Shipment, il Jordan's Smithing Hammer e una Kor Gem, e riportali a Jordan Stilwell, a Ironforge.", "Vorrei ricompensarti, se sei <disposto/disposta> ad accettare una cosa del genere. Non fraintendermi: la mia generosità dipende da quanto mi sarai d'aiuto, ma vedo che entrambi trarremmo grande beneficio da un'alleanza simile.\n\nForgerò per te un'arma degna di ciò che hai compiuto, un simbolo dell'essere paladino e della Luce, ma devi raccogliere gli oggetti che mi servono per crearla. Ho già cominciato a prendere appunti su di essi: serve solo qualcuno abbastanza coraggioso e abile da recuperarli. Che ne dici, {class}?", "Gli oggetti che cerchi saranno difficili da ottenere, ma ti assicuro che l'arma che forgerò per te varrà la fatica.\n\nSarà la mia opera migliore finora, e solo un piccolo compenso per il servizio che mi hai reso.", "Magnifico! Hai preso tutti gli oggetti.\n\nCon questi non dovrei avere problemi a forgiarti una grande arma. In realtà ho i progetti da parecchio tempo. Solo che non ho mai avuto l'occasione di raccogliere il materiale. Grazie, {name}.\n\nÈ bello riavere il martello di mio padre... e una gemma Kor. Non avrei mai pensato di vederne una con i miei occhi.", 0xcdb318ba, 0xc7646423, 0xfb00e058, 0x7e9cab3a, 0x803f6796, "....." },
  [1655] = { "Il carico di minerale di Bailor", "Porta il Jordan's Ore Shipment a Bailor Stonehand, a Loch Modan.", "Accidenti, mi hai fatto prendere un colpo, <ragazzo/ragazza>! Non vedi che ero perso nei miei pensieri?\n\nCosa dici? Il carico di Jordan... per Ironforge. Ahhh, sì, so di cosa parli. Gli ogre Mo'grosh... sono loro che hanno preso il carico di minerale del mio vecchio amico. La carovana veniva qui dalle Wetlands ed è finita in un'imboscata. La guardia sopravvissuta all'attacco è morta qualche giorno fa: il guaritore non è arrivato in tempo.\n\nSe vuoi il carico, dovrai andare a nord-est oltre il Loch. Dev'essere là da qualche parte.", "Allora, fortuna? Ah ah, quegli ogre non ti hanno ancora fatto la pelle, eh?", "Sì, sì, è questo. Ah! Se avessi saputo che saresti davvero <andato/andata> là fuori a combattere quegli ogre, ti avrei dato una lista di cose da prendere invece di questa sola. Ma non sei qui a fare affari per me, vero?\n\nUn patto è un patto: Jordan voleva un carico della mia lega, e quello avrà.\n\nSalutamelo, e stai <attento/attenta>, {class}.", 0xa7b78c4d, 0x20c7415e, 0x9cf966dc, 0x0aa0afd3, 0xfa19665f, ".....", nil, nil, 0xc6e76059, nil, nil },
  [1658] = { "Guastare il Wickerman Festival", "Trova il Wickerman Festival dei Forsaken nelle Tirisfal Glade. Fatto questo, torna dal Sergeant Hartman, a Southshore.", "Mi servono persone coraggiose che vadano nelle Tirisfal Glade a controllare il Wickerman Festival. Non ti mentirò: andare lassù sarà pericoloso. Le guardie della festa saranno particolarmente feroci. Comunque dobbiamo sapere quanto è grande la festa quest'anno, e quanti problemi ci causeranno i Forsaken durante l'Hallow's End.\n\nSe te la senti, va' a Tirisfal e spia la festa. Torna da me con le informazioni e farò in modo che tu riceva un buon compenso.", "Sei <salito/salita> nelle Tirisfal Glade a controllare? Di solito tengono la festa vicino all'Undercity...", "Ben fatto, {name}. Il Wickerman Festival continuerà a dare problemi finché agli abominevoli Forsaken sarà permesso di infestare i resti di Lordaeron. NON è un tributo degno di quel regno un tempo fiero, te lo dico io...\n\nEcco qualche moneta per le riparazioni che potrebbero servirti e, nello spirito della stagione, ho aggiunto anche qualche dolcetto che potrebbe piacerti. Buon Hallow's End: cerchiamo di renderlo il più sicuro possibile qui a Southshore.", 0xea538ce9, 0xaea7886b, 0xb5ed7ed6, 0x1e87c181, 0x044aeaed, "....." },
  [1661] = { "Il Tome of Nobility", "Parla con Duthorian Rall, a Stormwind.", "Ti saluto ancora una volta, {name}. Sono più fiero che mai di chiamarti <fratello/sorella>: la tua dedizione è un tributo a tutti noi.\n\nÈ giunto il momento che ti conceda un grande dono. Ma sappi questo: per ora te lo do liberamente, ma più avanti, quando il tempo lo permetterà, questo sarà una sfida molto più grande per tutti i paladini che sceglieranno di intraprendere la mia missione.\n\nParlami di nuovo e ti concederò un grande beneficio.", nil, "Congratulazioni, e che la Luce ti protegga.", 0x2923ea98, 0x0f3ca705, 0xb8e31e55, nil, 0x72ae1e80, "...m.", nil, nil, 0xe0eeab96, nil, nil },
  [1665] = { nil, "Porta il Bartleby's Mug a Burlguard", "Va bene, ecco il mio boccale. Aspetta! Lasciami finire quel che c'è dentro... ecco fatto.", "Ho visto il tuo combattimento con Bartleby. Ben fatto! Hai preso il suo boccale?", "Eccolo! Di sicuro non voleva separarsene, ma sei <stato/stata> convincente. Ben fatto.\n\nOra la tua lezione...", nil, 0x1a2aa8fa, 0xbe9a356b, 0xc1276dca, 0xd416acd3, "m...." },
  [1666] = { nil, "Parla con il Marshal Haggard.", "Hai imparato qualche mossa, ma ti farebbe comodo un'arma decente. Scommetto che, se parlassi con il Marshal Haggard, potrebbe aiutarti.\n\nIl Marshal Haggard vive in una villa nell'Elwynn Forest, all'Eastvale Lumber Camp. Ora è in pensione, ma durante la sua carriera ha raccolto molto equipaggiamento.\n\nDigli che ti mando io e, con un po' di fortuna, avrà un'arma in più da offrirti.", nil, "Chi è?\n\nBurlguard, sei tu?\n\nDovrai avvicinarti un po'. I miei occhi non sono più quelli di una volta.\n\nAvvicinandoti così, ti avevo preso per uno gnoll!", nil, 0x28259910, 0x2a45bdb6, nil, 0x9c239c26, "m..m." },
  [1667] = { nil, "Recupera la Haggard's Badge dall'accampamento di Dead-tooth Jack e torna da Marshal Haggard.", "Ti manda Burlguard, eh? Sì, ho delle armi di scorta qui, ma prima ho un compito per te...\n\nTempo fa un furfante dei Defias, Dead-tooth Jack, mi ha imbrogliato. Era buio, lui indossava una tabarda di Stormwind e l'ho scambiato per Marshal Dughan. Mi ha detto che gli serviva il mio vecchio distintivo da maresciallo di Stormwind e gliel'ho dato... poi è scoppiato a ridere ed è scappato prima che potessi prenderlo!\n\nRiprendi il mio distintivo! Probabilmente Dead-tooth Jack lo tiene nascosto nel suo accampamento, a sud.", "Hai il mio distintivo? Non voglio nemmeno pensare ai guai che Dead-tooth Jack potrebbe combinare con quello.", "Grande, l'hai trovato! Temevo fosse perduto per sempre, usato dai Defias per spacciarsi per un ufficiale di Stormwind. Be', ora non succederà, grazie a te.\n\nEcco alcune armi che usavo quando ero maresciallo. Le ho tenute in ottimo stato: scegli pure!", nil, 0xe3968aa6, 0x35913d6c, 0x0dd5019b, 0xaa14a96f, "m...." },
  [1678] = { nil, "Porta la Vejrek's Head a Muren Stormpike, a Ironforge.", "Se vuoi salire di grado tra i guerrieri, è meglio che tu sia <tosto/tosta>. Posso insegnarti nuove mosse, ma prima dimostrami che sai cavartela contro nemici veri.\n\nVejrek è il troll più duro che troverai da queste parti, ed è lui che devi battere. Ha una capanna tra le colline appena a sud di Frostmane Hold.\n\nPortami la testa di Vejrek e saprò che hai fegato.", "Sei <stato/stata> alla capanna di Vejrek, {name}? È puzza di {race} quella che sento addosso a te?", "Vejrek era proprio un brutto ceffo, eh? Ben fatto, {name}! Hai la stoffa giusta, ora cominciamo la lezione...\n\nForse non lo sai, ma una difesa solida è molto importante per un {class}. Ti tiene in piedi contro nemici che abbatterebbero altri, ed è proprio ciò di cui hanno bisogno i tuoi alleati.", nil, 0x8eeb8a4d, 0x97c7fda5, 0xbfd8004a, 0x4056a577, "m...." },
  [1679] = { nil, "Parla con Muren Stormpike.", "Salve, <guerriero/guerriera>! Sei molto promettente, ma devi ancora imparare qualche trucco, e Muren Stormpike è proprio il nano adatto a insegnartelo.\n\nPuoi trovare Muren nella Hall of Arms, nel Military Ward di Ironforge. Parla con lui quando sarai <pronto/pronta> a imparare cosa significa essere <un/una> <guerriero/guerriera>.", nil, "Ah, {name}. Ho sentito i guerrieri di Dun Morogh fare il tuo nome. Spero che tu non abbia passato tutto il tempo nelle birrerie!", nil, 0xdec45bd4, 0x8fd9e632, nil, 0x01c660f9, "m..m." },
  [1680] = { nil, "Parla con Tormus Deepforge.", "Ora che hai imparato qualche mossa, è il momento di procurarti un'arma decente. Parla con Tormus Deepforge. Può forgiarti un'arma che di sicuro ti piacerà.\n\nTroverai Tormus qui a Ironforge, alla Great Forge.", nil, "Ti manda Muren, eh? Sì, posso forgiarti una bella arma... ma prima ho un favore da chiederti.\n\nNon preoccuparti. È parecchio pericoloso e potresti lasciarci la pelle: proprio il genere di lavoro che un {class} desidera.", nil, 0xc2199bac, 0x02618112, nil, 0xf292e320, "m..m." },
  [1681] = { nil, "Porta un carico di Umbral Ore a Tormus Deepforge, a Ironforge.", "Il mio maestro, Sturgy Ironband, aveva un complesso a sud dell'Helm's Bed Lake, nella parte orientale di Dun Morogh. Lì insegnava l'arte del fabbro, ed era il migliore.\n\nMa un giorno uno dei suoi allievi gli portò un carico di uno strano minerale. Il maestro Ironband lo chiamò minerale umbrale e non vedeva l'ora di lavorarlo, ma poco dopo il suo arrivo... una banda di nani Dark Iron attaccò il complesso. Uccisero tutti!\n\nEntra nell'Ironband's Compound, {name}, e vendica la morte del mio maestro. E portami il carico di minerale umbrale che l'ha causata.", "Sei <entrato/entrata> nell'Ironband's Compound? Hai trovato il minerale umbrale?", "L'hai trovato! Ben fatto!\n\nSpero tu abbia ucciso una schiera di nani Dark Iron mentre cercavi. Temo che l'Ironband's Compound non sarà l'ultimo posto in cui li vedremo.\n\nMa grazie per il minerale, {name}. Non vedo l'ora di lavorarlo e scoprirne le proprietà.", nil, 0x4a772cf1, 0x9c8b9801, 0xb61614dd, 0xbd6d2250, "m...." },
  [1682] = { "Armi di ferro grigio", nil, nil, nil, "Ecco qualche arma, appena uscita dall'incudine e forgiata con il nuovo minerale umbrale che mi hai portato!\n\nTi prego, {name}, scegli tu!", 0x73849205, nil, nil, nil, 0x676432e2, ".mmm." },
  [1683] = { nil, "Porta l'Horn of Vorlus a Elanaria, a Darnassus.", "Prima che possa istruirti, devi mostrarmi la tua determinazione.\n\nIl satiro Vorlus Vilehoof ha trovato uno dei nostri pozzi lunari isolati, a sud-est del Ban'ethil Barrow Den. Ora ci sguazza dentro, profanando le sue acque pure con la sua sporcizia.\n\nTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e comincerò il tuo addestramento avanzato da <guerriero/guerriera>.\n\nIl sentiero per il pozzo lunare è ben nascosto, {name}, ma resta <concentrato/concentrata> e vigile e lo troverai.", "Hai il corno, {name}? Il nostro pozzo lunare è libero da quel demonio di Vorlus?", "Ben fatto, {name}. È bello sapere che Vorlus è sconfitto e il nostro pozzo lunare purificato, ed è bello vedere giovani guerrieri ansiosi di tenere la nostra amata Teldrassil libera dalla corruzione.\n\nOra cominciamo il tuo addestramento...", nil, 0x5adfba87, 0x8fb16149, 0x049695c0, 0x512c5bec, "m...." },
  [1684] = { nil, "Parla con Elanaria.", "Salute, <guerriero/guerriera>. La tua abilità cresce, ma nel tuo mestiere c'è più di quanto tu possa credere. Per progredire ancora, presto dovrai trovare un maestro.\n\nLa guerriera Elanaria vive a Darnassus, alla Warrior's Terrace. Può istruirti lei.", nil, "Ti saluto, {name}. Il tuo nome risuona forte a Darnassus, perché sei una promessa. Ma presto vedremo se hai la forza di volontà per seguire la via del {class}.", nil, 0x1d103619, 0xe3640e54, nil, 0xee8cf141, "m..m." },
  [1685] = { "La convocazione di Gakin", "Fai rapporto a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me l'aspetto, mi vieni incontro.\n\nHo perso abbastanza tempo a cercarti, quindi non ti trattengo oltre. Master Gakin ti ha convocato per un addestramento supplementare. Se fossi in te, andrei da lui il prima possibile.\n\nLo trovi nel seminterrato della taverna Slaughtered Lamb. A proposito, forse è meglio che quel posto resti un segreto. Non vogliamo che se ne parli in giro.", nil, "Era ora che ti facessi vedere. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.\n\nNon importa.\n\nSei <rimasto/rimasta> troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente terrà la testa sulle spalle a lungo.", 0xafbad200, 0xd830dab8, 0x7de17495, nil, 0x9da53ed7, "...m." },
  [1686] = { "L'ombra di Elura", "Porta 8 carichi di Elunite Ore e il Medallion of Elura a Elanaria, a Darnassus.", "Hai imparato molto, {name}. Ora ti forgeremo un'arma. Un'arma da guerriero.\n\nPer farlo, devi andare a Darkshore.\n\nTanto tempo fa una nave si schiantò sugli scogli vicino al faro di Auberdine, spargendo molte casse di Elunite Ore sul fondo dell'oceano.\n\nPrima devi sconfiggere la guardiana dell'elunite, la Shade of Elura. Era il capitano della nave, e si condannò a vagare negli abissi per proteggere il suo carico per sempre. Sconfiggila, prendi il suo medaglione e raccogli le casse di elunite perdute.", "Hai sconfitto la Shade of Elura, {name}? E hai l'Elunite Ore perduta?", "Coraggiosamente fatto, {name}.\n\nHai dato alla Shade of Elura la pace che meritava, e useremo l'elunite raccolta per forgiarti un'ottima arma.", 0x8040e914, 0x47fcac4e, 0x0ae1f260, 0x77ddb931, 0xe02c3ab9, "....." },
  [1688] = { nil, "Recupera il Surena's Choker per Gakin the Darkbinder, a Stormwind.", "Avevo un'allieva di nome Surena Caledon. Stava dove ora stai tu, desiderosa di imparare la magia degli stregoni e dotata di un talento non da poco. Inoltre era giovane e piacevole a vedersi. Se solo l'avessi capito allora, quella sgualdrina traditrice!\n\nQuella ladra è fuggita con uno dei Defias, Erlan Drudgemoor. Anche se la sua perdita conta poco, le avevo regalato un girocollo di bloodstone che devo riavere.\n\nLa sua vita ora non significa nulla per me. La troverai al Brackwell Pumpkin Patch. Recupera ciò che è mio.", "Anche i più anziani e saggi possono essere disarmati dalle astuzie della giovinezza e della bellezza, {name}. Un consiglio che faresti bene a ricordare per tutta la vita.", "Surena aveva talento, ma non abbastanza da padroneggiare da sola la magia degli stregoni. È un peccato vedere sprecato il talento, ma a volte è necessario.\n\nSpero che il mio investimento in te dia risultati diversi.", nil, 0xbd6285ef, 0x7fe37381, 0x1aeacf64, 0x26838f1f, "m...." },
  [1689] = { "Il vincolo", "Usando il Bloodstone Choker, evoca e sottometti un voidwalker, poi riporta il Bloodstone Choker a Gakin the Darkbinder, a Stormwind.", "Recuperando il mio girocollo e battendo Surena, hai dimostrato di essere almeno capace quanto lei.\n\nDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, sì, ma essere <uno/una> <stregone/strega> è molto di più.\n\nTi mostrerò come comandare un voidwalker, ma prima devi evocarne uno a un cerchio di evocazione e sottometterlo usando tutte le armi, fisiche e magiche, che hai a disposizione. Usa la magia di questo girocollo al cerchio di evocazione qui sotto.", "Non posso mostrarti come controllare un voidwalker finché non ne avrai sopraffatto uno.", "Te la sei cavata meglio di quanto mi aspettassi, {name}, ma bene quanto speravo. Ora puoi imparare a comandare il voidwalker che hai soggiogato, un alleato che troverai prezioso nelle prove che di certo ti attendono.\n\nPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, {name}.", 0x5926988f, 0x4d76bd4b, 0xe97faec4, 0xe581a55d, 0xfecce601, "....." },
  [1692] = { nil, "Porta la Case of Elunite a Smith Mathiel.", "Ho messo in una cassetta l'elunite che hai raccolto. Portala al fabbro Mathiel, e ti forgerà un'arma di elunite.\n\nMathiel è a sud, dall'altra parte di questo edificio.", "Salute, giovane {class}. Come possono servirti le mie abilità?", "Ah, Elunite Ore. È un metallo ottimo da lavorare, perché è benedetto dalla dea Elune in persona. Sarà un onore forgiarci delle armi.\n\nTi prego, aspetta mentre lavoro...", nil, 0x228e326e, 0x6be6ff55, 0x8c6ab610, 0xf4a34bbc, "m...." },
  [1693] = { "Armi di elunite", nil, nil, nil, "{name}, ho forgiato queste armi con l'elunite che mi hai portato. Ti prego, prendi quella che ti si addice di più.\n\nE devo ringraziarti. Lavorare l'elunite è un onore e un piacere.", 0x0ad2a7a8, nil, nil, nil, 0xf1481cc9, ".mmm." },
  [1698] = { nil, "Parla con Yorus Barleybrew.", "Yorus Barleybrew ha lanciato una sfida a tutti i guerrieri abili dell'Alliance. Aspetta alla Lakeshire Inn, a Redridge, e promette una grande ricompensa a chiunque superi la sua prova.", nil, "Ah! Così hai sentito della mia sfida, eh?\n\nBe', siediti e ascolta. Bevi qualcosa, e gustatelo... perché potrebbe essere l'ultimo.", nil, 0x341329a1, 0x3bd4b7dc, nil, 0xf107d207, "m..m." },
  [1699] = { "La Rethban Gauntlet", "Entra nelle Rethban Caverns, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo concesso.\n\nNon devi morire né liberare il tuo spirito.", "La mia sfida la chiamo Rethban Gauntlet. Per superare la prova devi solo entrare nelle Rethban Caverns, arrivare al primo bivio e tornare qui. Facile! Solo che ci sono un paio di intoppi...\n\nDevi tornare entro un'ora.\n\nLungo la strada ci sono mucchi di Redridge Gnolls.\n\nPrima di partire, devi bere un sorso della bevanda tipica della mia famiglia: il Barleybrew Scalder!\n\nAllora, che ne dici? Le Rethban Caverns sono sulle colline a nord di Lakeshire. Sei <pronto/pronta> per la Rethban Gauntlet?", "Il tempo stringe, {name}. Se fossi in te, mi sbrigherei...", "Ce l'hai fatta! Ben fatto! Tre urrà per {name}!", 0xd10a48fe, 0xa8194546, 0xfd08c428, 0x9b73f4f5, 0x9fe48580, "....." },
  [1700] = { nil, "Porta i Furen's Notes a Grimand Elmore.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e devo mandarli a Grimand Elmore. È qui nel Dwarven District, nell'armeria.\n\nE abbassati quando glieli dai. È orgogliosissimo delle sue capacità, e non gli piacerà l'idea di imparare qualcosa da me...", "Salve, e ben <trovato/trovata>. Come posso esserti utile?", "L'ha scritto Furen? Come osa! Gli ho insegnato tutto quello che sa! Pensare che possa insegnarmi qualcosa è oltraggioso! Oltraggioso!\n\nMm... però c'è qualcosa nei suoi appunti che vorrei provare...", nil, 0x7caa129c, 0x4e71336d, 0xe126afd2, 0x9f7c1433, "m...." },
  [1701] = { nil, "Raccogli i materiali che servono a Furen Longbeard e portaglieli a Stormwind.", "Ti ho dato un bello scudo, ma non dobbiamo fermarci qui. Conosco i segreti per fare un'armatura di maglia durissima. Non è facile e servono materiali molto rari, ma se sei <disposto/disposta> a fare il lavoro sul campo, te ne farò un pezzo.\n\nChe ne dici, {name}? Se accetti la sfida, ti darò una lista di cosa procurarti e dove trovarlo.", "Come procede la caccia al tesoro, {name}? Hai i materiali?", "Hai preso tutto? Incredibile! Avevo paura che quelle chimere ti avrebbero di sicuro <divorato/divorata>!\n\nBeh, cominciamo con quell'armatura...", nil, 0x17005a3a, 0x3f524efb, 0x9d29594a, 0x8da07437, "m...." },
  [1702] = { "Il fabbro di scudi", "Porta il Cask of Scalder a Furen Longbeard.", "Hai proprio dimostrato di che pasta sei <fatto/fatta> quando hai corso la Rethban Gauntlet, {name}. E io sono di parola. Ti darò la ricompensa che ti ho promesso...\n\nSolo che è a Stormwind.\n\nParla con il mio amico Furen Longbeard, nel Dwarven District di Stormwind. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.\n\nTieni, porta a Furen questa botticella di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.", "Salve! Che siccità, non trovi?", "Ah, Barleybrew Scalder. Roba ottima! Quindi sei <stato/stata> da Yorus, eh?\n\nPosso darti uno scudo, sì! Non ne troverai uno migliore, parola mia!", 0x798b8e48, 0xa9d5c007, 0x121a2fd8, 0x9fc39f0a, 0x9c18ee37, "....." },
  [1703] = { nil, "Porta i Furen's Notes a Mathiel.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e devo mandarli al fabbro Mathiel. Vive a Darnassus, che è piuttosto lontano, ma sono sicuro che sarà molto grato di imparare ciò che ho imparato io.", "Ti porgo i miei saluti, {class}.", "Sono interessanti, davvero molto interessanti. Il mio collega nanico Furen ha fatto una gran bella scoperta!\n\nGrazie, {name}. Sarà un onore applicare le sue nuove tecniche alle mie creazioni.", nil, 0x7d69410a, 0x9cfdd510, 0xc0241fbe, 0xe16816d1, "m...." },
  [1704] = { nil, "Porta i Furen's Notes a Klockmort Spannerspan.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e mi serve qualcuno che li porti a Klockmort Spannerspan. È un fabbro gnomesco di Ironforge e quando scoprirà quello che ho scoperto io... scommetto che si strapperà la barba dall'emozione.", "Buongiorno, o buona mattina, o buonasera. Da quaggiù non si capisce. Allora, hai affari per me?", "Oh, cielo! Questi appunti sono straordinari! E per di più... sono incredibili e stupefacenti e mi fanno tremare le ginocchia!\n\nFuren ha fatto una scoperta! Una vera scoperta! Non vedo l'ora di provare la sua nuova tecnica!", nil, 0x8704fda0, 0x6072da24, 0x40580185, 0xcf60d068, "m...." },
  [1705] = { nil, "Porta 20 fiale di Burning Blood e 1 Burning Rock a Grimand Elmore, a Stormwind.", "Odio ammetterlo, ma forse Furen ha davvero trovato qualcosa. Per esserne sicuro, però, dovrò provare le sue tecniche su un nuovo pezzo d'armatura. Se mi aiuti con i materiali, {name}, l'armatura sarà tua.\n\nPer fare questa armatura mi servono campioni di sangue ardente e una roccia ardente.\n\nL'unico posto che conosco dove trovarli è Duskwood. I worgen Nightbane che si sono stabiliti nella miniera di Roland's Doom hanno il sangue ardente, e il loro capo Gutspill avrà la roccia.\n\nChe la fortuna ti dia velocità, {name}.", "{name}, hai il sangue ardente e la roccia? Mi serviranno per completare l'armatura.", "Bel lavoro! Ora, se vuoi scusarmi, ho anch'io del lavoro da fare...", nil, 0x5a863d44, 0xd546c7a8, 0x78e76958, 0x46cd6b29, "m...." },
  [1706] = { "L'armatura di Grimand", nil, nil, nil, "Stento a crederci! La tecnica di Furen è stata un successo, e questa armatura dovrebbe resistere a sollecitazioni enormi.\n\nEccola, {name}. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per verificarla di persona.", 0x1b21ef14, nil, nil, nil, 0x8a3cf8c0, ".mmm." },
  [1708] = { "Corallo di ferro", "Porta $N1 carichi di Searing Coral a Klockmort Spannerspan, a Ironforge.", "Voglio provare le nuove tecniche di Furen Longbeard su un mio pezzo d'armatura. E visto che tu hai aiutato Furen e lui ha aiutato me, l'armatura sarà tua quando l'avrò finita!\n\nPer completarla mi serve un corallo speciale, il corallo ardente. Cresce in un solo posto: lungo la costa a sud di Menethil Harbor, nelle Wetlands.\n\nPortami abbastanza corallo ardente e mi metterò subito al lavoro sull'armatura. E sbrigati, {name}. Non vedo l'ora di cominciare, mi si attorcigliano le dita dei piedi!", "Ciao ciao, {name}! Hai il corallo ardente? Non vedo l'ora di mettermi al lavoro!", "È proprio questa la roba! Ben fatto! Ora lasciami fondere e battere tutto questo, così applico la tecnica di Furen insieme alla mia e vediamo cosa succede!\n\nOh cielo, oh cielo! Me lo sento che l'armatura sarà durissima, durissima, durissima!", 0x95d46a3a, 0xf862f256, 0x08ca6259, 0xa8ff5a9d, 0x51171b46, "....." },
  [1709] = { "La creazione di Klockmort", nil, nil, nil, "Ecco la tua armatura, {name}. Il procedimento di Furen ha funzionato in modo brillante! Perfetto! Meraviglioso, davvero!\n\nPotresti passarci sopra con una macchina d'assedio e tornerebbe subito in forma!", 0xe53f77d4, nil, nil, nil, 0xaafc1252, ".mmm." },
  [1710] = { nil, "Porta 20 Sunscorched Shells a Mathiel, a Darnassus.", "Il mio collega Furen Longbeard ha fatto una scoperta che non vedo l'ora di mettere alla prova. Voglio provarla su una nuova armatura che sto studiando, perché credo che le tecniche di Furen daranno risultati migliori.\n\nMi aiuterai? Se mi procuri quello che serve per fare l'armatura, ne farò un pezzo in più per te.\n\nMi servono i gusci d'uovo bruciati dal sole delle Highperch Wyverns che vivono a Highperch, nelle Thousand Needles. Cerca i gusci sotto i loro nidi e torna da me quando ne avrai abbastanza.", "Hai i gusci, {name}? Sono molto resistenti, e se ne può ricavare una lacca con cui rivestirò le maglie della mia nuova armatura.", "Ah, grazie. Andranno benissimo!\n\nComincerò subito a forgiare l'armatura...", nil, 0x5c836a66, 0x41c7b49e, 0x76aded81, 0x8386f94f, "m...." },
  [1711] = { "L'armatura di Mathiel", nil, nil, nil, "Ho finito il tuo pezzo d'armatura, e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono sposate perfettamente con le mie, e sono sicuro che questa armatura si rivelerà molto resistente.\n\nGrazie, {name}. E che ti serva bene nelle battaglie future.", 0xf31b6b88, nil, nil, nil, 0x39be4aab, ".mmm." },
  [1712] = { nil, "Porta gli oggetti elencati nella Bath'rah's Parchment a Bath'rah the Windwatcher, nell'Alterac.", "Ho passato secoli a sorvegliare questo luogo. Sorveglio, affinché un giorno io possa vedere cadere il grande Cyclonian. Ma non ho ancora trovato un campione capace di sconfiggere il signore del vento.\n\nForse quel campione sei tu.\n\nDimostramelo. Raccogli gli oggetti che mi servono per evocare Cyclonian e saprò che sei un grande guerriero. Forse allora potrai sconfiggerlo e ottenere il suo cuore di turbine.\n\nSe ci riuscirai, infonderò il potere del cuore in un'arma, e quell'arma la darò a te.\n\nEcco una pergamena con gli oggetti che mi servono.", "Hai gli oggetti, {name}? Raccoglierli è la prova che mi serve per sapere che hai la forza di affrontare Cyclonian.", "Hai raccolto gli oggetti per il mio incantesimo e mi hai mostrato la tua forza e la tua astuzia. Ma la prossima fase della nostra impresa è ancora più pericolosa.\n\nSperiamo che la tua forza non venga meno.", nil, 0x1225d934, 0xb7e52410, 0xf41610df, 0x5f294daf, "m...." },
  [1713] = { "L'evocazione", "Porta il Whirlwind Heart a Bath'rah Windwatcher.", "Sono pronto a compiere il rituale per evocare Cyclonian. Quando sarà evocato, dovrai sconfiggerlo e prendere il suo cuore di turbine. Lo userò per infondere in un'arma il potere di Cyclonian.\n\n{name}, sei <pronto/pronta> ad affrontare il signore del vento?", "{name}, devo avere il cuore di turbine!", "Ce l'hai fatta! Hai sconfitto Cyclonian e ottenuto il Whirlwind Heart!", 0x7256d21c, 0x03db61b0, 0x1c7ae6a8, 0xaae28055, 0xba56a949, "....." },
  [1714] = { nil, nil, nil, "Il calderone ribolle. I suoi vapori ti chiamano...", "Gli amuleti affondano lentamente nelle profondità del calderone...\n\nUna grossa bolla sale alla superficie del liquido e scoppia...\n\n...E appare un grumo ribollente di roccia fusa.", nil, nil, nil, 0x43a67631, 0xe2842b83, "mmm.." },
  [1715] = { nil, "Fai rapporto a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", nil, nil, nil, nil, 0xd830dab8, nil, nil, nil, "m.mmm" },
  [1716] = { "Il divoratore di anime", "Parla con Takar the Seer, nelle Barrens.", "Un sayaad è un divoratore di anime, un dominatore di volontà e un tentatore di cuori. Non conosce altro che il male.\n\nI racconti licenziosi chiamano questo demone con il suo nome comune: succube per le femmine, incubo per i maschi.\n\nServe uno stimolo per attirare la creatura. Con un simbolo d'amore come esca, risponderà di certo al tuo richiamo. Sconfiggila e rendila il tuo strumento.\n\nSarà però difficile trovare una cosa del genere. Dovresti parlare con Takar the Seer. Lo troverai nelle Barrens di Kalimdor, vicino a Camp Taurajo.", nil, "La traversata è stata difficile, {name}? Hai fatto molta strada per parlare con me. Ma non temere, so perché Gakin ti ha mandato, ed è stato saggio a farlo, perché posso aiutarti nella tua ricerca.", 0xc90e9da6, 0x5802ee48, 0xc237a24d, nil, 0xcb33ee38, "...m." },
  [1717] = { "La convocazione di Gakin", "Fai rapporto a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", nil, nil, nil, 0xafbad200, 0xd830dab8, nil, nil, nil, "..mmm" },
  [1719] = { "La rissa", "Uccidi Big Will, poi parla con Klannoc Macleod sulla Fray Island.", "Se vuoi imparare da me, prima devi superare The Affray. È una sfida che noi della Fray Island amiamo proporre ai guerrieri emergenti che si credono duri, e se superi questa prova saprò che lo sei.\n\nPer cominciare, entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei <pronto/pronta> e ti manderà contro degli sfidanti.\n\nBatti tutti gli sfidanti e chiamerà Big Will. Uccidi Big Will e torna da me nel tempo concesso.", "Hai completato la tua sfida?", "Ben fatto, {name}. Hai superato The Affray!\n\nSei <un/una> <guerriero/guerriera> <degno/degna>, ed è un onore per me addestrarti...", 0x71a4d209, 0x1003a249, 0x7ffe012e, 0x518944b1, 0xbf82ca14, "....." },
  [1738] = { nil, "Recupera l'Heartswood da Ashenvale e portalo a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", "In preparazione al tuo arrivo, ho usato la mia vista per scrutare il mondo e attraverso le nebbie del tempo. Ho trovato ciò che cerchi.\n\nNella War of the Ancients, due amanti caddero insieme in battaglia. Dove esalarono l'ultimo respiro crebbe un albero noto come heartswood, simbolo del loro amore immortale.\n\nDovrebbe bastare a tentare una succube. Lo troverai tra le rovine di Ordil'Aran, nella parte nord-occidentale della foresta di Ashenvale.", "La tua ricerca ha avuto successo, {name}?", "Sì, vedo che andrà benissimo, lasciami solo lavorarci un momento...\n\nTakar è un tipo pieno di risorse da avere intorno, vero? Se solo riuscissi a convincerlo a tornare alla civiltà.", nil, 0x83326afc, 0x89350d42, 0xe8536f8f, 0x78395298, "m...." },
  [1739] = { "Il vincolo", "Usando l'Heartswood Core, evoca e sottometti una succube, poi riporta l'Heartswood Core a Gakin the Darkbinder, allo Slaughtered Lamb.", "Usando l'heartswood core, potrai lanciare un incantesimo al cerchio di evocazione nella cripta qui sotto per aprire un portale attraverso cui passerà la succube.\n\nFa' attenzione, {name}: le succubi hanno sopraffatto anche le menti più forti.\n\nUna volta che l'avrai battuta e rimandata nel vuoto, torna da me e ti mostrerò come richiamarla e controllarla.", "A volte mi chiedo se Surena non fosse una succube travestita, mandata a distorcere e piegare la mia mente... Ah! Credo di darle troppo credito.", "Ben fatto, ben fatto, {name}. Vedo che abbiamo fatto bene a decidere di addestrarti. La tua prestazione di certo non delude.\n\nNon ho scrupoli a mostrarti come controllare la succube che hai appena vincolato. Osserva attentamente.", 0x5926988f, 0xc70dfe93, 0x0b92f947, 0x111f48b5, 0xc7d74427, "....." },
  [1740] = { "L'Orb of Soran'ruk", "Trova 3 Soran'ruk Fragments e 1 Large Soran'ruk Fragment e riportali a Doan Karhan, nelle Barrens.", "Quando i demoni della Legion cadono in disgrazia, i loro spiriti vengono imprigionati in sfere e distribuiti ai loro maghi e stregoni.\n\nMolte furono portate dai loro servitori su Azeroth. Anche in frammenti possiedono ancora i poteri dei demoni intrappolati all'interno.\n\nL'orb of Soran'ruk fu spezzata in due pezzi: uno fu ulteriormente spezzato per essere usato dagli accoliti del Twilight's Hammer a Blackfathom Deeps. L'altro pezzo, più grande, era in possesso di un mago a Shadowfang Keep. Trovali e potrò ricomporla.", "Mi ci sono voluti molti anni per raccogliere i pezzi dell'orb of Zargain, ma mi è stata molto utile, come sono certo che l'orb of Soran'ruk sarà utile a te.", "Sì... La sfera non era molto frammentata, e quasi tutti i pezzi sono qui. È semplice ricrearli, rendere di nuovo intera Soran'ruk.\n\nHo dedicato la mia vita allo studio delle sfere della Burning Legion e alla loro ricostruzione. Mi hai fatto un favore raccogliendo questi pezzi da studiare, e te li restituirò, completamente ricostruiti, nella forma che preferisci.", 0x331f56fd, 0xad372c46, 0x452768a2, 0x04ccd818, 0xafeadf79, "....." },
  [1758] = { nil, "Parla con Krom Stoutarm, a Ironforge.", "Servirà più di un semplice cerchio di evocazione per richiamare un felhunter da sfidare.\n\nI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tome of the Cabal, che è perduto per noi da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un felhunter senza aiuto.\n\nForse Krom Stoutarm può aiutarti. Ormai è uno stregone itinerante, e passa le giornate ad accumulare testi antichi e a gironzolare per la biblioteca di Ironforge.", nil, "Tome of the Cabal? Mmm... mi suona familiare. Però qui non l'ho mai visto, e credimi, ricordo ogni libro che leggo.\n\nMmm...\n\nAh, sì! Ne ho visto dei riferimenti nei cataloghi della biblioteca.", nil, 0x6185a67d, 0x0a3411a2, nil, 0xeb681de0, "m..m." },
  [1778] = { "Il Tome of Divinity", "Parla con Tiza Battleforge, a Ironforge.", nil, nil, nil, 0xe91f21c0, 0x04be03fc, nil, nil, nil, "..mmm" },
  [1779] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1780] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", "Porterò questi ai bambini oggi stesso. Ti prego, sii prudente, {class} dal buon cuore. Non capita spesso che <uomini/donne> del tuo carattere si facciano vedere in città, ma hai dimostrato che i paladini qui a Stormwind non volteranno mai le spalle a chi ha bisogno.\n\nAddio.", nil, "Sei <tornato/tornata> così in fretta, {name}. E cosa hai compiuto nel tempo trascorso lontano dalla cattedrale?\n\nHai aiutato una nobile causa? Forse hai imparato il valore della carità o qualcosa di più sui tuoi obblighi verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come.... Beh, sono colpito, {name}: queste sono di certo le azioni di chi segue la Luce e mette gli altri davanti a se stesso.\n\nUn tale sacrificio sarà sempre ricompensato, col tempo.", 0xe91f21c0, 0x0f3ca705, 0xa762da4f, nil, 0xe78d8da6, "...m.", nil, nil, 0xc898f87d, nil, nil },
  [1781] = { "Il Tome of Divinity", "Porta il Symbol of Life a Gazin Tenorm, a Stormwind.", "Prendi questo, {name}. Si chiama Symbol of Life.\n\nHai dimostrato carità e pazienza, e ora è giunto il momento di vedere se sei abbastanza potente da concentrare uno dei più grandi doni della Luce.\n\nIl mio amico Gazin è tornato di recente da uno scontro con alcuni Defias a Elwynn, vicino all'Heroes' Vigil: è scampato per un pelo. È vicino all'altare, dove i nostri sacerdoti gli curano le ferite.\n\nPrendi il Symbol e parla con lui. Se riuscirai ad aiutarlo, ci parleremo di nuovo presto. Che tu possa crogiolarti nella gloria della Luce.", nil, "*coff*\n\nPiacere di conoscerti, {class}. Non badare alle mie ferite: questa volta il buon sacerdote qui può occuparsi del vecchio Gazin. Non avrò bisogno del potere di quel Symbol of Life che hai lì... non ancora, almeno.\n\nQuindi ti ha mandato Duthorian a parlarmi, eh? D'accordo. Ti racconterò esattamente cosa è successo a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse potrai ancora aiutarci tutti.", 0xe91f21c0, 0xdb6e8f90, 0x25218c29, nil, 0x4ea87484, "...m." },
  [1782] = { "L'armatura di Furen", nil, nil, nil, "Ecco la tua armatura, {name}. Resisterà agli assalti più forti, o non mi chiamo Furen Longbeard!\n\nE devo ringraziarti. Ho imparato molto lavorando con i materiali\n\nche mi hai portato. Credo che un giorno farò un'altra scoperta!\n\nManderò ciò che ho imparato ad altri\n\nfabbri dell'Alliance.\n\nDirò loro che sei <stato/stata> di grande aiuto, e forse vorranno ricambiare il favore.", 0xe60f030a, nil, nil, nil, 0x2efb420d, ".mmm." },
  [1783] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1784] = { "Il Tome of Divinity", "Recupera un Dark Iron Script dai nani Dark Iron vicino all'Helm's Bed e torna da Muiredon Battleforge, a Ironforge.", "Prima che cadessi in battaglia, Muiredon e io avevamo quasi sconfitto una delle spie Dark Iron vicino a quella casetta. Avevamo visto il loro capitano impartire ordini e cercammo di ucciderlo e prendere gli ordini.\n\nAlcuni membri del consiglio di Ironforge non credono ancora alla presenza dei nani Dark Iron a Dun Morogh. Ottenendo uno di quegli scritti, non solo avremo la prova dei loro movimenti, ma forse anche un'idea di cosa stiano tramando.\n\nProcurati uno di quegli scritti e riportalo a Muiredon, {name}.", "Sei <tornato/tornata>! Sono contento di vederlo, {name}. Le mie ferite sono guarite e sono quasi pronto a tornare al lago dell'Helm's Bed, appena riuscirò a convincere mia moglie che starò bene.", "Ahah! Ce l'hai fatta! Hai salvato Narm e hai trovato la prova che mia moglie deve portare al consiglio. Sei una benedizione della Luce come poche che abbia mai visto... esclusa mia moglie, naturalmente.\n\nGrazie ancora, {name}.", 0xe91f21c0, 0x552cfc26, 0x107e3082, 0x1db426a0, 0x9d225682, "....." },
  [1785] = { "Il Tome of Divinity", "Parla con Tiza Battleforge, a Ironforge.", nil, nil, nil, 0xe91f21c0, 0x04be03fc, nil, nil, nil, "..mmm" },
  [1786] = { "Il Tome of Divinity", "Prendi il Symbol of Life e resuscita Henze Faulk, a Elwynn.", "Henze e io eravamo arrivati all'Heroes' Vigil, un'isola in mezzo allo Stone Cairn Lake, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati oltre i nostri confini e volevamo prove da portare ai consiglieri del re.\n\nAbbiamo visto un paio di quei farabutti esaminare dei documenti e li abbiamo attaccati. Purtroppo siamo stati subito sopraffatti da altri maghi.\n\nHenze li ha trattenuti mentre io fuggivo... quello sciocco, a fare l'eroe.\n\nÈ ancora là fuori, Henze. Puoi aiutarci, {name}?", nil, "Grazie, <fratello/sorella>.\n\nVedendoti impugnare il Symbol of Life, posso supporre che ti abbiano mandato Duthorian o Gazin?\n\nSono caduto per mano degli incantatori Defias mentre Gazin e io cercavamo di sottrarre loro i piani: ho resistito abbastanza a lungo da permettere a Gazin di fuggire, ma alla fine la loro magia mi ha sopraffatto.\n\nMa tu sei <riuscito/riuscita> a riportarmi indietro: la capacità di usare il Symbol non è concessa a chiunque, {name}. È di buon auspicio per te esserci <riuscito/riuscita> con la tua stessa fede.", 0xe91f21c0, 0x4eb84a7e, 0xddf00bb3, nil, 0xd0b687e0, "...m.", nil, nil, nil, nil, 0xe3b33add },
  [1787] = { "Il Tome of Divinity", "Recupera una Defias Script dai Defias Rogue Wizards di Elwynn e torna da Gazin Tenorm a Stormwind.", "Avremo tempo di parlare ancora del Symbol più avanti. Ora l'importante è prendere le carte che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn e, speriamo, capire qualcosa dei loro piani.\n\nPer ora non sono in condizione di combattere, {name}. Pensi di essere abbastanza forte da prendere quelle carte ai Defias qui sull'isola?\n\nSe ci riesci, portale a Gazin e digli che sto bene.", "Henze è al sicuro, {name}? Ci sei <riuscito/riuscita>?\n\nTra la tua abilità con le armi e il potere della Luce, immagino che la Heroes' Vigil sia al sicuro da qualsiasi minaccia dei Defias, ma questo spetta al re e ai suoi consiglieri dirlo.", "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è certamente con te, {name}!", 0xe91f21c0, 0x09e322c6, 0xb07e8693, 0x78c1898e, 0x3eda4356, "....." },
  [1788] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", "Porterò lo scritto ai consiglieri del re dopo che Duthorian l'avrà esaminato, ma nel frattempo dovresti andare subito a parlare con Duthorian. Vorrà di sicuro darti una pacca sulla spalla!\n\nGrazie ancora, {name}. Spero di rivederti. Sei di certo <un/una> <alleato/alleata> che sono fiero di chiamare <amico/amica>.", nil, "Oggi hai fatto bene, {name}. Dovresti essere <orgoglioso/orgogliosa> di ciò che hai compiuto.\n\nAncor di più, dovresti essere <fiero/fiera> delle tue capacità. Non tutti possono usare il potere del Symbol of Life. Invocare la Luce per riportare in vita i morti significa che sei <pronto/pronta> per uno dei più grandi onori di un paladino: il potere della resurrezione.\n\nAvrai il potere di riportare in vita i compagni caduti, proprio come hai fatto con Henze.\n\nStammi bene, {name}. La Luce risplende su di te e dovresti accoglierla completamente.", 0xe91f21c0, 0x0f3ca705, 0xd2692364, nil, 0xaecaeccf, "...m." },
  [1790] = { nil, nil, nil, nil, "Sbrigati, {name}: se fallisci, più di una vita è appesa a un filo.\n\nSe per qualche motivo non riesci ad aiutare Gazin e Henze, torna da me e ti darò un altro Symbol of Life per i tuoi viaggi.\n\nNon scambiare il mio aiuto per semplice carità: devi dimostrare il tuo valore come chiunque altro, {class}, e i fallimenti continui potrebbero ricadere su di te più avanti.", nil, nil, nil, nil, 0x3f42f7b3, "mmmm." },
  [1791] = { "Il Windwatcher", "Parla con Bath'rah the Windwatcher.", "Ora che hai imparato la postura del berserker, vorrai una bella arma con cui usarla.\n\nParla con Bath'rah the Windwatcher, un eremita troll che vive tra le Alterac Mountains e le Western Plaguelands. È un abile fabbricante d'armi e un potente sciamano.\n\nPer trovare Bath'rah, va' al fiume che scorre lungo il fianco orientale di Tarren Mill. Seguilo verso nord: Bath'rah è accampato vicino a delle rovine sulla riva orientale del fiume.", nil, "Hai viaggiato lontano, giovane <guerriero/guerriera>. Vedo il fuoco nei tuoi occhi. Cerchi un'arma di grande potere, vero?\n\nPosso aiutarti nella tua impresa. E tu puoi aiutarmi nella mia.", 0xb6038666, 0x3cac39b3, 0xea9f0083, nil, 0xbb0930b4, "...m." },
  [1792] = { "L'arma del turbine", nil, nil, nil, "Ho il cuore di turbine e sono pronto a infonderlo nell'arma che sceglierai.\n\nScegli la tua arma, {name}, e sappi che il suo potere è il potere di Cyclonian.", 0x2c74e831, nil, nil, nil, 0x0ae24e1b, ".mmm." },
  [1793] = { "Il Tome of Valor", nil, nil, nil, "È stato dimostrato che la Luce è con te, {name}, ma man mano che i tempi si fanno più pericolosi diventa importante sapere quale forza si celi sotto la carne. Quando demoni, draghi o qualsiasi altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, in qualunque situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1794] = { "Il Tome of Valor", nil, nil, nil, "È stato dimostrato che la Luce è con te, {name}, ma man mano che i tempi si fanno più pericolosi diventa importante sapere quale forza si celi sotto la carne. Quando demoni, draghi o qualsiasi altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, in qualunque situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1795] = { "Il vincolo", "Usando il Tome of the Cabal, evoca e sottometti un felhunter, poi riporta il Tome of the Cabal a Strahad Farsan, a Ratchet.", "Se sei sufficientemente <preparato/preparata>, allora cominciamo. Lascia che ti spieghi il procedimento.\n\nComincerò creando il cerchio di evocazione di base. Quando avrò finito, i miei accoliti useranno le verghe di incanalamento per creare il cerchio maggiore.\n\nUna volta fatto, leggi l'incantesimo dal Tome of the Cabal e il felhunter verrà richiamato. Sta' <attento/attenta>, {name}. Un felhunter è un avversario potente, e mi piacerebbe vederti con la testa ancora sulle spalle.", "Ogni stregone dovrebbe avere un felhunter ai suoi ordini. Per quanto sia difficile da domare, i poteri che conferisce al suo padrone superano di gran lunga il costo.", "Devo dire che sono colpito, {name}. Quando ho affrontato il mio felhunter, ne sono uscito vivo per un pelo. Sento che hai il potenziale per diventare uno degli stregoni più potenti di quest'era.", 0x5926988f, 0x90eb7a27, 0x5d293135, 0x6582b8e7, 0x2ff39446, "....." },
  [1796] = { "Componenti per l'Enchanted Gold Bloodrobe", "Porta le Robes of the Arcana a Menara Voidrender, nelle Barrens.", "Il primo oggetto che ti aiuterò a creare è una veste. Raccoglierai gli oggetti per me e li metteremo insieme. Poi, se ci riuscirai, avrai il primo di molti oggetti che ti renderanno più potente e ti aiuteranno nelle tue lotte.\n\nPer cominciare, devi avere delle Robes of the Arcana confezionate. Un sarto può farle per te, oppure puoi comprarle da qualcun altro (sarei molto colpita se riuscissi a farle da te), ma in ogni caso portami le vesti e procederemo da lì.", "Come procede la tua ricerca delle vesti, {name}? Le hai create tu? Trovo che tocchi personali del genere rendano l'infusione della magia ancora più dolce. Dà un maggiore senso di realizzazione. Ma capisco se scegli la via più rapida e le fai fare a qualcun altro: c'è qualcosa da dire a favore di una tale... ambizione.", "Andrà benissimo, {name}.\n\nOgni oggetto magico deve partire da un oggetto di alta qualità. Più impegno e abilità si mettono in un oggetto, più grande è la magia che può contenere. I componenti rari e più costosi trattengono meglio la magia. Non ti pentirai di aver fatto trasformare le vesti in quelle che creeremo per te più avanti.", 0x7fee9266, 0x691cf117, 0x8dcf592c, 0x9a22f6e6, 0x7badf4fc, "....." },
  [1798] = { "Alla ricerca di Strahad", "Parla con Strahad Farsan, nelle Barrens.", "È tempo che tu impari a evocare il felhunter, {name}. Non ho qui i reagenti e gli oggetti necessari per insegnartelo, quindi dovrai cercare un altro membro della nostra cerchia ristretta, Strahad Farsan.\n\nRisiede nel porto goblin di Ratchet. Gli manderò a dire del tuo arrivo.", nil, "{name}? Ah, certo. Il nostro ultimo talento prodigio. Temo che la realtà non possa essere all'altezza della leggenda.\n\nNon importa, sei qui per imparare, non per sentirmi fare battute tra me e me.", 0x884bfbbe, 0xe2b6e98e, 0xd43a3b1f, nil, 0x5156dbd9, "...m." },
  [1799] = { "Frammenti dell'Orb of Orahil", "Parla con gli accoliti di Menara nella torre sopra Ratchet e scegli quale dei loro sentieri seguire.\n\nPoi porta un Infernal Orb a Tabetha, nel Dustwallow Marsh.", "Bene, allora cominciamo.\n\nLa prima cosa che devi fare è parlare con i miei accoliti all'interno. Scegli quale dei loro sentieri seguire: ti spiegheranno meglio.\n\nPoi devi recarti a Desolace e ottenere un Infernal Orb da uno degli stregoni del Mannoroc Coven. È quella sfera che purificherai con l'aiuto di una maga di nome Tabetha, nel profondo sud del Dustwallow Marsh. Ti aiuterà per via della nostra storia comune.\n\nTe lo ripeto, non tornare finché non avrai fatto entrambe le cose che ti ho chiesto.", "E dato che ovviamente non sei <un/una> <mago/maga>, mi chiedo se posso fidarmi di te. Sento su di te l'odore del potere arcano, ma sembri essere <sfuggito/sfuggita> al fetore della corruzione che accompagna così volentieri quelli come te.\n\nSì, {class}... qualcuno della classe {class} è venuto a chiedere il mio aiuto.\n\nBeh, cosa posso fare per te, {name}?", "Oh, quindi ti ha mandato Menara. Va bene... suppongo che tu possa restare come mio ospite per il momento. Ma devi avere qualche faccenda urgente: forse sei qui in cerca di un potere perduto? Forse mi sbaglio. Forse la corruzione non è poi così lontana da te.", 0x2e1f0446, 0x3a7840aa, 0x122ee87b, 0x4ac12eff, 0x5dae030e, "....." },
  [1806] = { "La prova della rettitudine", "Attendi che Jordan Stilwell finisca di forgiare un'arma per te.", "Perché non andiamo alla forgia e cominciamo? Mi preparo al tuo arrivo da tempo, quindi non dovrebbe volerci molto.\n\nQuando avremo finito, sarai molto più <pronto/pronta> a difendere la Luce di quanto tu sia mai stato, questo te lo giuro.\n\nSarò in parte sincero, {name}: vedere i risultati delle tue imprese mi rende un po' invidioso. Ma sapere di poter contribuire alle tue avventure in modo significativo mi dà una certa gioia.", nil, "Eccola, {name}. Un'arma degna di <un/una> <campione/campionessa> della Luce come te. L'ho chiamata come un grande paladino nanico che era mio amico. Si chiamava Verigan... Bosch Verigan.\n\nTi prego, accettala da parte mia e di mia moglie. Abbiamo un grande debito con te, e il mondo sarà un posto più sicuro con qualcuno della tua abilità in giro per le terre.", 0xcdb318ba, 0xe85d14f5, 0x581863b3, nil, 0x3f6f787f, "...m." },
  [1860] = { "Parlare con Jennea", "Parla con Jennea Cannon, a Stormwind.", "Noi maghi abbiamo un compito da svolgere, un compito vitale per la sicurezza di Stormwind e della foresta di Elwynn.\n\nJennea Cannon conosce i dettagli. Studia nel santuario dei maghi, nel quartiere dei maghi di Stormwind. Dovresti raggiungerla in fretta.", nil, "Ti hanno mandato ad aiutarmi nel mio compito, {name}? Bene. È confortante vedere giovani maghi ansiosi di aiutare la nostra causa...\n\nQuale causa, chiedi? A tempo debito, giovane. Saprai... a tempo debito.", 0x7b586e0a, 0x17610de7, 0x833e5a0d, nil, 0x5a63396f, "...m." },
  [1861] = { nil, "Porta un campione del Mirror Lake a Jennea Cannon, a Stormwind.", "Questo mondo è stato vittima di enormi lotte mistiche, che hanno strappato le correnti magiche da canali un tempo stabili. Cerchiamo di capire quali effetti abbiano causato questi cambiamenti, e alcuni di noi temono il peggio!\n\nMa ne rivelerò di più in seguito. Ora abbiamo bisogno che tu raccolga informazioni.\n\nEcco, prendi questa fiasca. Va' ai piedi della cascata del Mirror Lake, a sud-ovest delle porte di Stormwind, e preleva un campione d'acqua. Riportamelo, così potrò analizzarlo in cerca di contaminazioni magiche.", "Hai il campione, {name}? Il flusso della magia a Stormwind e a Elwynn è stato alterato, e devo sapere se sta filtrando nell'acqua.", "Grazie, {name}. Analizzerò quest'acqua in cerca di proprietà magiche. Speriamo che non ne abbia, o potremmo scoprire che chi beve troppo a lungo dal Mirror Lake ne subirà effetti negativi.\n\nEcco, {name}. Prendi questa sfera o questo bastone come segno del tuo servizio. Che ti sia utile.", nil, 0x299fa3ef, 0x14519806, 0x40ceafc2, 0x6ddff8d3, "m...." },
  [1879] = { "Parla con Bink", "Parla con Bink, a Ironforge.", "{name}! Bink, la mia collega gnoma a Ironforge, manda a dire che ha un compito da svolgere e non si affiderà a nessuno se non a un mago! Sei tu <quel/quella> <mago/maga>, {name}?\n\nSe sì, parla con Bink. Passa il suo tempo nella Hall of Mysteries, nel Mystic Ward di Ironforge.", nil, "Oh, vedo che sei promettente, sì che lo sei! Ma per essere un buon mago serve più che promettere. E se non sei un buon mago, allora sei un cattivo mago. E i cattivi maghi sono parte del problema, sì che lo sono!\n\nUps, sto correndo troppo. Cominciamo dall'inizio!", 0x0b59c7b3, 0x88f317f6, 0x9decdd73, nil, 0x88e0f9f8, "...m." },
  [1880] = { nil, "Porta a Bink il suo Mage-tastic Gizmonitor.", "Noi maghi facciamo molto più che agitare le dita e creare scintille carine! Controlliamo la magia, il tessuto stesso del nostro mondo! E questo richiede grande cura e determinazione. E conoscenza... tantissima conoscenza!\n\nUno dei miei congegni, il mage-tastic gizmonitor, raccoglie e conserva quella conoscenza in quantità enormi! Ma è andato perduto! Quando siamo fuggiti dalla nostra casa, Gnomeregan, l'ho lasciato in un forziere in una delle nostre capanne fuori dalla città, e ora il posto brulica di gnomi lebbrosi!\n\nTi prego, {name}, recupera il mio gizmonitor!", "Hai trovato il gizmonitor? Devo averlo prima che la sua riserva di energia si esaurisca!", "Oh, che splendida giornata! Quando ho costruito il gizmonitor non immaginavo quanto ne sarei diventata dipendente. Ora posso ricominciare i miei studi!\n\nGrazie, {name}! E tieni: questi sono stati i miei primi strumenti da maga. Sono un po' graffiati, ma ben collaudati. Scegli pure: sono sicura che li troverai utili entrambi.", nil, 0x694f2e68, 0x57d62cf0, 0x0ab359eb, 0x9bceb030, "m...." },
  [1919] = { nil, "Parla con Jennea Cannon, a Stormwind.", nil, nil, nil, nil, 0x17610de7, nil, nil, nil, "m.mmm" },
  [1920] = { "Indaga sul Blue Recluse", "Prendi una Cantation of Manifestation e un Chest of Containment coffers da dietro Jennea Cannon. Porta 3 Filled Containment Coffers a Jennea, al Wizard's Sanctum.", "È stato segnalato un disturbo alla taverna Blue Recluse, nel Mage Quarter. Strane creature invisibili ora si aggirano per la taverna, e temo che lì si sia formata una frattura di mana.\n\nVoglio che tu indaghi nella taverna e catturi quelle creature. Usa la cantation of manifestation nella taverna per rendere visibili le creature, sottomettile, poi usa un containment coffer per catturarle. Quando ne avrai abbastanza, torna da me con gli scrigni pieni, quelli vuoti e la cantation.", "Hai catturato le creature, {name}? Devono essere studiate per capire il motivo del loro arrivo.", "Davvero ben fatto! Studierò queste creature e, con diligenza e fortuna, scoprirò come sono scivolate nel nostro mondo.\n\nIl tuo valore per la società dei maghi cresce, {name}.", 0x99ff705d, 0x444df4da, 0x4b931a51, 0x411e2ef3, 0x4083ef42, "....." },
  [1921] = { "Raccogliere materiali", "Porta 10 Linen e i 6 Charged Rift Gems a Wynne Larson, a Stormwind.", "Hai servito bene i tuoi compagni maghi, e ora è il momento di indossare la tua veste da mago. Wynne Larson può confezionare la tua veste, ma devi portarle i materiali necessari\n\nLa veste sarà di linen, facile da trovare, ma devi procurarti anche delle charged rift gem, e l'unico luogo noto in cui trovarle è la Silver Stream Mine di Loch Modan, lasciate in casse dalla lega dei minatori nanici.\n\nRaccogli il linen e le gemme e portali a Wynne Larson, alla Larson Clothiers, nel Mage District.", "Salve, {name}. Jennea mi ha detto che saresti <venuto/venuta>. Hai qualcosa per me?", "Sì, sono ottimi pezzi di linen. Posso farne una bella veste. E dopo averci intessuto le rift gem, avremo un abito degno di un mago!", 0x2c5cc185, 0xcd459eaf, 0x8bb64794, 0xf3259f6b, 0xbad1677b, "....." },
  [1938] = { nil, "Porta l'Ur's Treatise on Shadow Magic all'High Sorcerer Andromath, a Stormwind.", "Molto tempo fa, tre maghi studiavano in questa torre finché uno di loro non cadde nelle arti oscure. Fu esortato ad allontanarsi da quella magia malvagia, ma non riuscì a resistere. E così fu bandito.\n\nIl nuovo dominio del mago caduto è la torre di Ilgalar, a Redridge, e ha portato con sé un libro potente: l'Ur's Treatise on Shadow Magic.\n\nNoi, i maghi di Stormwind, vorremmo che quel libro ci fosse restituito. Entra nella torre di Ilgalar, trova il tomo nella sua biblioteca e portamelo.", "Hai il libro, {name}? I suoi segreti non sono destinati a chi non è addestrato, e scandagliarne le profondità può portare alla rovina e alla perdizione.", "Temevo che Morganth avesse nascosto il libro altrove, o che avesse trovato un modo per aprirlo e leggerne il contenuto.\n\nÈ bello vedere che non è così, e che i sigilli che abbiamo posto sull'Ur's Treatise on Shadow Magic reggono ancora.", nil, 0x5da24331, 0x84778b51, 0xc0beaebd, 0x6a7c0b88, "m...." },
  [1939] = { nil, "Parla con l'High Sorcerer Andromath.", "L'High Sorcerer Andromath desidera parlarti, {name}. Si trova in cima al santuario dei maghi, nel quartiere dei maghi di Stormwind.\n\nSarebbe saggio parlargli, perché Andromath è uno dei maghi più potenti che non siano rinchiusi a Dalaran. Un consiglio da lui è davvero un consiglio prezioso.", nil, "Salute, {name}. Sono lieto di vederti, e spero tu abbia tempo per ascoltare le parole di un vecchio...", nil, 0xc9d25e42, 0xb1ce8c24, nil, 0x10407ead, "m..m." },
  [1940] = { nil, "Porta 8 Pristine Spider Silk a Wynne Larson, a Stormwind.", "Il tuo servizio è stato incrollabile, {name}. Credo che sia forse giunto il momento che tu abbia un abito più raffinato, più adatto al tuo rango di <mago/maga> <esperto/esperta>. Se raccogli i materiali necessari, faremo confezionare la veste.\n\nDevi entrare a Duskwood e dare la caccia ai ragni carrion recluse. Estrai la loro seta, ma andrà bene solo la seta più fine e pura. Quando ne avrai abbastanza, portala a Wynne Larson, qui nel Mage District, alla Larson Clothiers. Confezionerà la tua veste.", "Ah, sì. I maghi del Wizard's Sanctum mi hanno detto che saresti <venuto/venuta> a parlarmi. Hai la seta richiesta?", "Begli esemplari, questi. Mi metto subito al lavoro!", nil, 0x2674cfe7, 0x31b76a02, 0x5407cd18, 0x48d28ffb, "m...." },
  [1941] = { nil, nil, nil, nil, "Ecco la tua veste. È una delle migliori che abbia mai fatto! Indossala con orgoglio, e quando te lo chiederanno... di' che l'hai presa alla Larson Clothiers!", nil, nil, nil, nil, 0xf4dc234a, "mmmm." },
  [1942] = { nil, nil, nil, nil, "Il tuo abito è pronto! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatto un po' corto, così da avanzare un po' di seta per me, vero?\n\nSto solo scherzando. Ti starà benissimo, e sarà perfetto sia per l'avventura sia per le cene formali. Buon divertimento!", nil, nil, nil, nil, 0x7bdf4eeb, "mmmm." },
  [1961] = { "Raccogliere materiali", nil, nil, nil, nil, 0x2c5cc185, nil, nil, nil, nil, ".mmmm" },
  [1978] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
})
